code.java:
class Solution {
    public int minStartValue(int[] nums){
        int prefix=0,minimum=0;
        for(int value:nums){
            prefix+=value;
            minimum=Math.min(minimum,prefix);
        }
        return 1-minimum;
    }
}

code.kotlin:
class Solution {
    fun minStartValue(nums:IntArray):Int{
        var prefix=0;
        var minimum=0;
        for(value in nums){
            prefix+=value;
            minimum=minOf(minimum,prefix)
        };
        return 1-minimum
    }
}

code.cpp:
class Solution {
    public: int minStartValue(vector<int>& nums){
        int prefix=0,minimum=0;
        for(int value:nums){
            prefix+=value;
            minimum=min(minimum,prefix);
        }
        return 1-minimum;
    }
};
